#!/usr/bin/env node
// Generates the job listing types for every app from schema/job.schema.json.
//
//   node schema/generate.mjs          write the generated files
//   node schema/generate.mjs --check  fail if a generated file is out of date
//
// Needs Node 22+ and gofmt on PATH. No npm dependencies.

import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const schemaPath = join(root, "schema/job.schema.json");
const schema = JSON.parse(readFileSync(schemaPath, "utf8"));

const HEADER = "Code generated by schema/generate.mjs from schema/job.schema.json. DO NOT EDIT.";

const outputs = {
  go: join(root, "apps/service/internal/models/listing.gen.go"),
  ts: join(root, "apps/website/src/types/job.gen.ts"),
  py: join(root, "apps/discord-bot/src/backend/mongo/collections/job_schema.py"),
};

// ---- reading the schema ---------------------------------------------------

const defs = Object.entries(schema.$defs).map(([name, def]) => ({ name, def }));
const enums = defs.filter(({ def }) => def.enum);
const objects = [
  ...defs.filter(({ def }) => def.type === "object"),
  { name: schema.title, def: schema },
];

function refName(node) {
  return node.$ref.slice("#/$defs/".length);
}

/** Describes a property as { kind, name?, items?, nullable }. */
function describe(node) {
  if (node.$ref) return { kind: "ref", name: refName(node), nullable: false };

  if (node.anyOf) {
    const inner = node.anyOf.find((option) => option.type !== "null");

    return { ...describe(inner), nullable: true };
  }

  const types = [node.type].flat();
  const nullable = types.includes("null");
  const type = types.find((entry) => entry !== "null");

  if (type === "array") return { kind: "array", items: describe(node.items), nullable };
  if (node["x-format"] === "object-id") return { kind: "object-id", nullable };
  if (node.format === "date-time") return { kind: "date", nullable };

  return { kind: type, nullable };
}

function fail(message) {
  throw new Error(`schema/job.schema.json: ${message}`);
}

// ---- naming ---------------------------------------------------------------

function pascal(snake) {
  return snake
    .split("_")
    .filter(Boolean)
    .map((word) => word[0].toUpperCase() + word.slice(1))
    .join("");
}

/** JobType -> JOB_TYPE, WFHStatus -> WFH_STATUS. */
function screaming(name) {
  return name
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1_$2")
    .toUpperCase();
}

function commentLines(text, prefix) {
  return text ? text.split("\n").map((line) => `${prefix} ${line}`.trimEnd()) : [];
}

// ---- Go -------------------------------------------------------------------

function goType(shape) {
  const base = {
    string: "string",
    integer: "int",
    boolean: "bool",
    date: "time.Time",
    "object-id": "primitive.ObjectID",
  }[shape.kind];

  if (shape.kind === "array") return `[]${goType(shape.items)}`;

  const name = shape.kind === "ref" ? shape.name : base;

  if (!name) fail(`no Go type for ${JSON.stringify(shape)}`);

  return shape.nullable ? `*${name}` : name;
}

function goStruct({ name, def }) {
  const lines = [...commentLines(def["x-go-comment"], "//"), `type ${name} struct {`];

  for (const [key, node] of Object.entries(def.properties)) {
    const go = node["x-go"] ?? {};

    if (go.skip) continue;

    const bson = go.omitempty ? `${key},omitempty` : key;
    const json = go.json ?? key;

    lines.push(...commentLines(node.description, "\t//"));
    lines.push(
      `\t${go.name ?? pascal(key)} ${goType(describe(node))} \`bson:"${bson}" json:"${json}"\``,
    );
  }

  lines.push("}");

  return lines.join("\n");
}

function goEnum({ name, def }) {
  const descriptions = def["x-enum-descriptions"] ?? {};
  const lines = [...commentLines(def.description, "//"), `type ${name} string`, "", "const ("];

  for (const value of def.enum) {
    lines.push(...commentLines(descriptions[value], "\t//"));
    lines.push(`\t${value} ${name} = "${value}"`);
  }

  lines.push(")");

  return lines.join("\n");
}

function generateGo() {
  const blocks = defs.map((entry) => (entry.def.enum ? goEnum(entry) : goStruct(entry)));

  blocks.push(goStruct({ name: schema.title, def: schema }));

  const source = [
    `// ${HEADER}`,
    "",
    "package models",
    "",
    "import (",
    '\t"time"',
    "",
    '\t"go.mongodb.org/mongo-driver/bson/primitive"',
    ")",
    "",
    blocks.join("\n\n"),
    "",
  ].join("\n");

  return execFileSync("gofmt", { input: source, encoding: "utf8" });
}

// ---- TypeScript -----------------------------------------------------------

function tsDocumentName(name) {
  return `${name}Document`;
}

function tsType(shape) {
  const base = {
    string: "string",
    integer: "number",
    boolean: "boolean",
    date: "Date",
    "object-id": "ObjectId",
  }[shape.kind];

  if (shape.kind === "array") return `${tsType(shape.items)}[]`;

  let name = base;

  if (shape.kind === "ref") {
    name = schema.$defs[shape.name].enum ? shape.name : tsDocumentName(shape.name);
  }

  if (!name) fail(`no TypeScript type for ${JSON.stringify(shape)}`);

  return shape.nullable ? `${name} | null` : name;
}

function tsEnum({ name, def }) {
  const constant = `${screaming(name)}_VALUES`;

  return [
    ...(def.description ? ["/**", ...commentLines(def.description, " *"), " */"] : []),
    `export const ${constant} = [`,
    ...def.enum.map((value) => `  "${value}",`),
    "] as const;",
    "",
    `export type ${name} = (typeof ${constant})[number];`,
  ].join("\n");
}

function tsInterface({ name, def }) {
  const required = new Set(def.required ?? []);
  const lines = [];

  if (def.description && name === schema.title) {
    lines.push("/**", ...commentLines(def.description, " *"), " */");
  }

  lines.push(`export interface ${tsDocumentName(name)} {`);

  for (const [key, node] of Object.entries(def.properties)) {
    if (node.description) {
      lines.push("  /**", ...commentLines(node.description, "   *"), "   */");
    }

    lines.push(`  ${key}${required.has(key) ? "" : "?"}: ${tsType(describe(node))};`);
  }

  lines.push("}");

  return lines.join("\n");
}

function generateTs() {
  return [
    `// ${HEADER}`,
    "",
    'import type { ObjectId } from "mongodb";',
    "",
    [...enums.map(tsEnum), ...objects.map(tsInterface)].join("\n\n"),
    "",
  ].join("\n");
}

// ---- Python ---------------------------------------------------------------

function pyTuple(name, annotation, values) {
  return [`${name}: Final[${annotation}] = (`, ...values.map((value) => `    "${value}",`), ")"];
}

function pyEnum({ name, def }) {
  return [
    ...commentLines(def.description, "#"),
    `${name} = Literal[`,
    ...def.enum.map((value) => `    "${value}",`),
    "]",
    ...pyTuple(`${screaming(name)}_VALUES`, `tuple[${name}, ...]`, def.enum),
  ].join("\n");
}

function pyFields({ name, def }) {
  const prefix = screaming(name);
  const keys = Object.keys(def.properties);
  const required = new Set(def.required ?? []);

  return [
    `# Every field a ${name} document can carry, in schema order.`,
    ...pyTuple(`${prefix}_FIELDS`, "tuple[str, ...]", keys),
    "",
    `# The ${name} fields that are always present.`,
    ...pyTuple(
      `${prefix}_REQUIRED_FIELDS`,
      "tuple[str, ...]",
      keys.filter((key) => required.has(key)),
    ),
  ].join("\n");
}

function generatePy() {
  return [
    `"""${HEADER}"""`,
    "",
    "from __future__ import annotations",
    "",
    "from typing import Final, Literal",
    "",
    `LISTING_COLLECTION: Final[str] = "${schema["x-collection"]}"`,
    "",
    [...enums.map(pyEnum), ...objects.map(pyFields)].join("\n\n"),
    "",
  ].join("\n");
}

// ---- main -----------------------------------------------------------------

const generated = { go: generateGo(), ts: generateTs(), py: generatePy() };
const check = process.argv.includes("--check");
const stale = [];

for (const [language, path] of Object.entries(outputs)) {
  const content = generated[language];
  let current = null;

  try {
    current = readFileSync(path, "utf8");
  } catch {
    // The file does not exist yet.
  }

  if (current === content) continue;

  if (check) {
    stale.push(relative(root, path));
  } else {
    writeFileSync(path, content);
    console.log(`wrote ${relative(root, path)}`);
  }
}

if (stale.length > 0) {
  console.error(`Out of date: ${stale.join(", ")}`);
  console.error("Run `node schema/generate.mjs` and commit the result.");
  process.exit(1);
}

if (check) console.log("Generated job types are up to date.");
